import csvfrom django.core.management.base import BaseCommandfrom catalog.models import Phoneclass Command(BaseCommand):    help = 'Import phones from CSV file'    def handle(self, *args, **options):        csv_file_path = 'phones.csv'        try:            with open(csv_file_path, 'r', encoding='utf-8-sig') as file:                # Указываем разделитель ; (точка с запятой)                reader = csv.DictReader(file, delimiter=';')                for row in reader:                    print(f"DEBUG: {row}")  # Временная отладка                    phone = Phone(                        id=int(row['id']),                        name=row['name'],                        price=float(row['price']),                        image=row['image'],                        release_date=row['release_date'],                        lte_exists=row['lte_exists'].lower() == 'true',                    )                    phone.save()                    self.stdout.write(f'Добавлен телефон: {phone.name}')            self.stdout.write(self.style.SUCCESS('Импорт завершен!'))        except FileNotFoundError:            self.stdout.write(self.style.ERROR('Файл phones.csv не найден!'))        except Exception as e:            self.stdout.write(self.style.ERROR(f'Ошибка: {e}'))